const body = ($('Запуск сметы').first().json.body) || {};
const positions = Array.isArray(body.positions) ? body.positions : [];
return positions.map(p => ({ json: p }));

const orig = ($('Развернуть позиции').item.json) || {};
return { json: {
  doc_id: orig.id || null,
  position: orig.name || null,
  amount: orig.amount,
  classification: { статья: 'Прочее', признак: 'спорно', обоснование: 'Сервис классификации недоступен (квота/сеть) после повторных попыток — требуется ручная проверка', confidence: 0 },
  needs_review: true,
  model: 'error-fallback'
} };

const cls = ($json.classification) || {};
const orig = ($('Развернуть позиции').item.json) || {};
return { json: {
  id: orig.id || null,
  name: orig.name || null,
  статья: cls.статья || 'Прочее',
  признак: cls.признак || 'спорно',
  amount: (orig.amount != null ? orig.amount : $json.amount),
  doc_number: orig.doc_number || null,
  обоснование: cls.обоснование || null,
  ссылка: cls.ссылка || null,
  вид_услуги: cls.вид_услуги || null,
  confidence: (cls.confidence != null ? cls.confidence : null)
} };
